import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { UserSession } from 'src/app/models/usersession';
import { UserService } from 'src/app/services/emis/user.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-stc-dashboard',
  templateUrl: './stc-dashboard.page.html',
  styleUrls: ['./stc-dashboard.page.scss'],
})
export class StcDashboardPage implements OnInit {

  airArray = [];
  Type: any;

  constructor(private router: Router,
    private route: ActivatedRoute, private userSession: UserSessionService,
    private userService: UserService
  ) { }

  ngOnInit() {
  }

  ionViewDidEnter(){
    this.route.queryParams.subscribe((params) => {
      this.Type = params['Type'];
      console.log("Type",this.Type)
    })
    if(this.userSession.emis_usertype() == 8){
      this.airArray = [{
        id: 1,
        menu: 'Tamil Mozhi Karpom', // HM
        image: 'assets/images/nilp/NILP.svg',
        url: '/tabs/stc-activity'
      }]
    }else{
      this.userService.RSTMModuleCheck(this.userSession.emis_username()).subscribe(res =>{
        if(res.dataStatus){
          if(this.userSession.emis_usertype() == 39){
            this.airArray = [{
              id: 2,
              menu: 'RSTC', // BRTE
              image: 'assets/icons/school_cleaning.svg',
              url: '/tabs/stc-activity'
            }]
          }
        }else{
          this.airArray = [];
        }
      })
    }
  }

  goToMenu(item){
    this.router.navigate([item.url], {queryParams: {Type : item.id}});
  }

  navigateBack(){
    this.router.navigate(['/tabs/home']);
  }

}
